-- CarFix schema based on db'.sql + extensions for app logic
-- Create/recreate database outside this script (see setup_db.ps1)

BEGIN;

CREATE TABLE IF NOT EXISTS public."Roles"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."Statuses"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Statuses" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."Suppliers"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Phone" text NOT NULL,
    CONSTRAINT "PK_Suppliers" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."Services"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text,
    "Price" numeric NOT NULL,
    CONSTRAINT "PK_Services" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."Users"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Login" text NOT NULL,
    "Password" text NOT NULL,
    "RoleId" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Roles" FOREIGN KEY ("RoleId") REFERENCES public."Roles"("Id")
);

CREATE TABLE IF NOT EXISTS public."Cars"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "VIN" text NOT NULL,
    "Brand" text NOT NULL,
    "Model" text NOT NULL,
    "Year" integer NOT NULL,
    "PlateNumber" text NOT NULL,
    "Mileage" integer NOT NULL,
    "ClientId" integer NOT NULL,
    CONSTRAINT "PK_Cars" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Cars_Users" FOREIGN KEY ("ClientId") REFERENCES public."Users"("Id")
);

CREATE TABLE IF NOT EXISTS public."Orders"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "DateCreated" timestamp with time zone NOT NULL,
    "DateFinished" timestamp with time zone,
    "StatusId" integer NOT NULL,
    "AutomobileId" integer NOT NULL,
    "MechanicId" integer NOT NULL,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Orders_Statuses" FOREIGN KEY ("StatusId") REFERENCES public."Statuses"("Id"),
    CONSTRAINT "FK_Orders_Cars" FOREIGN KEY ("AutomobileId") REFERENCES public."Cars"("Id"),
    CONSTRAINT "FK_Orders_Users" FOREIGN KEY ("MechanicId") REFERENCES public."Users"("Id")
);

CREATE TABLE IF NOT EXISTS public."Comments"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "Text" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "IsFinalClientReview" boolean NOT NULL DEFAULT false,
    CONSTRAINT "PK_Comments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Comments_Orders" FOREIGN KEY ("OrderId") REFERENCES public."Orders"("Id")
);

CREATE TABLE IF NOT EXISTS public."Parts"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Article" text NOT NULL,
    "Name" text NOT NULL,
    "Quantity" integer NOT NULL,
    "PurchasePrice" numeric NOT NULL,
    "SalePrice" numeric NOT NULL,
    "SupplierId" integer NOT NULL,
    CONSTRAINT "PK_Parts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Parts_Suppliers" FOREIGN KEY ("SupplierId") REFERENCES public."Suppliers"("Id")
);

CREATE TABLE IF NOT EXISTS public."OrderParts"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "PartId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    CONSTRAINT "PK_OrderParts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderParts_Orders" FOREIGN KEY ("OrderId") REFERENCES public."Orders"("Id"),
    CONSTRAINT "FK_OrderParts_Parts" FOREIGN KEY ("PartId") REFERENCES public."Parts"("Id")
);

CREATE TABLE IF NOT EXISTS public."OrderServices"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "ServiceId" integer NOT NULL,
    "ActualPrice" numeric NOT NULL,
    "IsCompleted" boolean NOT NULL DEFAULT false,
    CONSTRAINT "PK_OrderServices" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderServices_Orders" FOREIGN KEY ("OrderId") REFERENCES public."Orders"("Id"),
    CONSTRAINT "FK_OrderServices_Services" FOREIGN KEY ("ServiceId") REFERENCES public."Services"("Id")
);

CREATE TABLE IF NOT EXISTS public."Payments"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "Amount" numeric NOT NULL,
    "Method" text NOT NULL,
    CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Payments_Orders" FOREIGN KEY ("OrderId") REFERENCES public."Orders"("Id")
);

CREATE TABLE IF NOT EXISTS public."Shifts"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "DayOfWeek" text NOT NULL,
    "UserId" integer,
    CONSTRAINT "PK_Shifts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Shifts_Users" FOREIGN KEY ("UserId") REFERENCES public."Users"("Id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS public."UserServices"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "ServiceId" integer NOT NULL,
    CONSTRAINT "PK_UserServices" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserServices_Users" FOREIGN KEY ("UserId") REFERENCES public."Users"("Id"),
    CONSTRAINT "FK_UserServices_Services" FOREIGN KEY ("ServiceId") REFERENCES public."Services"("Id")
);

CREATE TABLE IF NOT EXISTS public."PartRequests"
(
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ItemName" text NOT NULL,
    "Quantity" integer NOT NULL,
    "Note" text NOT NULL DEFAULT '',
    "UserId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PartRequests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PartRequests_Users" FOREIGN KEY ("UserId") REFERENCES public."Users"("Id")
);

