SELECT setval(pg_get_serial_sequence('public."Users"', 'Id'), (SELECT MAX("Id") FROM public."Users"));
SELECT setval(pg_get_serial_sequence('public."Services"', 'Id'), (SELECT MAX("Id") FROM public."Services"));
SELECT setval(pg_get_serial_sequence('public."UserServices"', 'Id'), (SELECT MAX("Id") FROM public."UserServices"));
